import React from 'react';
import UserProfile from './UserProfile';
import AdminPanel from './AdminPanel';

const ProfilePage = () => {
  // ВРЕМЕННО
  const role = 'user'; // потом придёт из auth

  return role?.toLowerCase() === 'admin'
    ? <AdminPanel />
    : <UserProfile />;
};

export default ProfilePage;
